begin; do $$ declare r text; begin foreach r in array array['workspace_query_owner','workspace_review_ingest_owner'] loop perform set_config('votus_review_facade_down.'||r,pg_has_role(current_user,r,'SET')::text,true); if not pg_has_role(current_user,r,'SET') then execute format('grant %I to %I',r,current_user); end if; end loop; end $$;
drop policy workspace_query_owner_review_select on public.review_item; drop policy review_item_authenticated_read on public.review_item; create policy review_item_authenticated_read on public.review_item for select to authenticated using(true); create or replace view public.review_item_unresolved_count with (security_invoker=false) as select count(*)::integer unresolved_count from public.review_item where resolved_at is null;
set role workspace_query_owner; drop function workspace_api.review_items(integer,integer); drop function workspace_private.review_item_is_authorized(uuid); reset role; revoke select on public.review_item from workspace_query_owner; drop index public.review_item_authorized_unresolved_idx;
set role workspace_review_ingest_owner; drop policy workspace_query_owner_review_scope_select on workspace_private.review_item_section_scope; revoke select on workspace_private.review_item_section_scope from workspace_query_owner; reset role;
do $$ declare r text; begin foreach r in array array['workspace_review_ingest_owner','workspace_query_owner'] loop if current_setting('votus_review_facade_down.'||r,true)='false' then execute format('revoke %I from %I',r,current_user); end if; end loop; end $$; commit;
